import React, { useState, useEffect } from 'react';
import {
  Grid,
  Card,
  CardContent,
  Typography,
  Button,
  Box,
  Alert,
  CircularProgress,
  Chip,
  LinearProgress,
  Divider
} from '@mui/material';
import {
  Analytics,
  Category,
  Store,
  Assessment,
  CheckCircle,
  Error,
  Warning,
  Info
} from '@mui/icons-material';

import { apiService, SystemStatus } from '../services/api';
import { socketService } from '../services/socket';

const Dashboard: React.FC = () => {
  const [systemStatus, setSystemStatus] = useState<SystemStatus | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [connectionStatus, setConnectionStatus] = useState<string>('disconnected');

  useEffect(() => {
    fetchSystemStatus();
    
    // Check WebSocket connection status
    setConnectionStatus(socketService.getConnectionState());
    
    // Set up periodic status updates
    const interval = setInterval(fetchSystemStatus, 30000); // Update every 30 seconds
    
    return () => clearInterval(interval);
  }, []);

  const fetchSystemStatus = async () => {
    try {
      const response = await apiService.getSystemStatus();
      
      if (response.success && response.data) {
        setSystemStatus(response.data);
        setError(null);
      } else {
        setError(response.error?.message || 'Failed to fetch system status');
      }
    } catch (err: any) {
      setError('Unable to connect to backend server');
      console.error('System status error:', err);
    } finally {
      setLoading(false);
    }
  };

  // Helper functions for quick actions
  const handleQuickAction = (actionType: string) => {
    console.log(`Quick action clicked: ${actionType}`);
    // TODO: Navigate to specific optimization form
    // For now, just show an alert
    alert(`${actionType} optimization will be available soon!`);
  };

  const isFeatureAvailable = (featureType: string): boolean => {
    if (!systemStatus) return false;
    
    switch (featureType) {
      case 'cohort':
        // Cohort requires LOB data
        return systemStatus.lob_status && Object.values(systemStatus.lob_status).some(Boolean);
      case 'lob':
        // LOB requires LOB data
        return systemStatus.lob_status && Object.values(systemStatus.lob_status).some(Boolean);
      case 'category':
        // Category requires data files
        return systemStatus.data_files && Object.values(systemStatus.data_files).some(Boolean);
      case 'full_store':
        // Full store requires any data
        return (systemStatus.data_files && Object.values(systemStatus.data_files).some(Boolean)) ||
               (systemStatus.lob_status && Object.values(systemStatus.lob_status).some(Boolean));
      default:
        return false;
    }
  };

  const getAvailabilityStatus = (featureType: string): string => {
    if (!systemStatus) return 'Unknown';
    
    const available = isFeatureAvailable(featureType);
    if (available) {
      return 'Ready';
    }
    
    switch (featureType) {
      case 'cohort':
      case 'lob':
        return 'Need LOB Data';
      case 'category':
        return 'Need Category Data';
      case 'full_store':
        return 'Need Data Files';
      default:
        return 'Not Available';
    }
  };

  const getAvailabilityColor = (featureType: string): 'success' | 'warning' | 'error' => {
    const available = isFeatureAvailable(featureType);
    return available ? 'success' : 'warning';
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="400px">
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Alert severity="error" sx={{ mb: 2 }}>
        {error}
        <Button onClick={fetchSystemStatus} sx={{ ml: 2 }}>
          Retry
        </Button>
      </Alert>
    );
  }

  return (
    <Box>
      <Typography variant="h4" gutterBottom>
        Planogram Optimization Dashboard
      </Typography>
      
      {/* System Status */}
      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Typography variant="h6" gutterBottom>
            System Status
          </Typography>
          <Grid container spacing={2}>
            <Grid item xs={12} sm={6} md={3}>
              <Box>
                <Typography variant="body2" color="text.secondary">
                  System Health
                </Typography>
                <Chip 
                  label={systemStatus?.system_health || 'Unknown'} 
                  color="success" 
                  size="small" 
                />
              </Box>
            </Grid>
            <Grid item xs={12} sm={6} md={3}>
              <Box>
                <Typography variant="body2" color="text.secondary">
                  Active Jobs
                </Typography>
                <Typography variant="h6">
                  {systemStatus?.active_jobs || 0}
                </Typography>
              </Box>
            </Grid>
            <Grid item xs={12} sm={6} md={3}>
              <Box>
                <Typography variant="body2" color="text.secondary">
                  Store Templates
                </Typography>
                <Typography variant="h6">
                  {systemStatus?.store_templates?.length || 0}
                </Typography>
              </Box>
            </Grid>
            <Grid item xs={12} sm={6} md={3}>
              <Box>
                <Typography variant="body2" color="text.secondary">
                  Data Files
                </Typography>
                <Typography variant="h6">
                  {systemStatus?.data_files ? 
                    Object.values(systemStatus.data_files).filter(Boolean).length : 0
                  } / {systemStatus?.data_files ? Object.keys(systemStatus.data_files).length : 0}
                </Typography>
              </Box>
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      {/* Quick Actions */}
      <Typography variant="h5" gutterBottom sx={{ mt: 4 }}>
        Quick Actions
      </Typography>
      
      <Grid container spacing={3}>
        <Grid item xs={12} sm={6} md={3}>
          <Card 
            sx={{ 
              cursor: 'pointer',
              transition: 'all 0.2s',
              '&:hover': {
                transform: 'translateY(-2px)',
                boxShadow: 4
              }
            }}
            onClick={() => handleQuickAction('cohort')}
          >
            <CardContent>
              <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                <Analytics color="primary" sx={{ fontSize: 40, mr: 2 }} />
                <Box>
                  <Typography variant="h6">
                    Cohort Planogram
                  </Typography>
                  <Chip 
                    label={getAvailabilityStatus('cohort')} 
                    size="small" 
                    color={getAvailabilityColor('cohort')}
                    variant="outlined"
                  />
                </Box>
              </Box>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                Generate cohort-based planograms for specific LOBs
              </Typography>
              <Button 
                variant="contained" 
                fullWidth 
                disabled={!isFeatureAvailable('cohort')}
                startIcon={<Analytics />}
              >
                {isFeatureAvailable('cohort') ? 'Start Cohort' : 'Data Required'}
              </Button>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <Card 
            sx={{ 
              cursor: 'pointer',
              transition: 'all 0.2s',
              '&:hover': {
                transform: 'translateY(-2px)',
                boxShadow: 4
              }
            }}
            onClick={() => handleQuickAction('lob')}
          >
            <CardContent>
              <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                <Store color="primary" sx={{ fontSize: 40, mr: 2 }} />
                <Box>
                  <Typography variant="h6">
                    LOB Optimization
                  </Typography>
                  <Chip 
                    label={getAvailabilityStatus('lob')} 
                    size="small" 
                    color={getAvailabilityColor('lob')}
                    variant="outlined"
                  />
                </Box>
              </Box>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                Optimize by Line of Business (iPhone, iPad, Mac, etc.)
              </Typography>
              <Button 
                variant="contained" 
                fullWidth 
                disabled={!isFeatureAvailable('lob')}
                startIcon={<Store />}
              >
                {isFeatureAvailable('lob') ? 'Start LOB' : 'Data Required'}
              </Button>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <Card 
            sx={{ 
              cursor: 'pointer',
              transition: 'all 0.2s',
              '&:hover': {
                transform: 'translateY(-2px)',
                boxShadow: 4
              }
            }}
            onClick={() => handleQuickAction('category')}
          >
            <CardContent>
              <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                <Category color="primary" sx={{ fontSize: 40, mr: 2 }} />
                <Box>
                  <Typography variant="h6">
                    Category Optimization
                  </Typography>
                  <Chip 
                    label={getAvailabilityStatus('category')} 
                    size="small" 
                    color={getAvailabilityColor('category')}
                    variant="outlined"
                  />
                </Box>
              </Box>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                Optimize specific product categories
              </Typography>
              <Button 
                variant="contained" 
                fullWidth 
                disabled={!isFeatureAvailable('category')}
                startIcon={<Category />}
              >
                {isFeatureAvailable('category') ? 'Start Category' : 'Data Required'}
              </Button>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <Card 
            sx={{ 
              cursor: 'pointer',
              transition: 'all 0.2s',
              '&:hover': {
                transform: 'translateY(-2px)',
                boxShadow: 4
              }
            }}
            onClick={() => handleQuickAction('full_store')}
          >
            <CardContent>
              <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                <Assessment color="primary" sx={{ fontSize: 40, mr: 2 }} />
                <Box>
                  <Typography variant="h6">
                    Full Store
                  </Typography>
                  <Chip 
                    label={getAvailabilityStatus('full_store')} 
                    size="small" 
                    color={getAvailabilityColor('full_store')}
                    variant="outlined"
                  />
                </Box>
              </Box>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                Optimize all products for complete store
              </Typography>
              <Button 
                variant="contained" 
                fullWidth 
                disabled={!isFeatureAvailable('full_store')}
                startIcon={<Assessment />}
              >
                {isFeatureAvailable('full_store') ? 'Start Full Store' : 'Data Required'}
              </Button>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Enhanced System Information */}
      <Grid container spacing={3} sx={{ mt: 2 }}>
        {/* Data Files Status */}
        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Data Files Status
              </Typography>
              <Box sx={{ mb: 2 }}>
                {systemStatus?.data_files && Object.entries(systemStatus.data_files).map(([category, available]) => (
                  <Box key={category} sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                    {available ? (
                      <CheckCircle color="success" sx={{ mr: 1, fontSize: 20 }} />
                    ) : (
                      <Error color="error" sx={{ mr: 1, fontSize: 20 }} />
                    )}
                    <Typography variant="body2" sx={{ textTransform: 'capitalize' }}>
                      {category.replace('_', ' ')}
                    </Typography>
                  </Box>
                ))}
              </Box>
              <Divider sx={{ my: 2 }} />
              <Typography variant="body2" color="text.secondary">
                Available: {systemStatus?.data_files ? 
                  Object.values(systemStatus.data_files).filter(Boolean).length : 0
                } / {systemStatus?.data_files ? Object.keys(systemStatus.data_files).length : 0} files
              </Typography>
            </CardContent>
          </Card>
        </Grid>

        {/* LOB Status */}
        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Line of Business Status
              </Typography>
              <Box sx={{ mb: 2 }}>
                {systemStatus?.lob_status && Object.entries(systemStatus.lob_status).map(([lob, available]) => (
                  <Box key={lob} sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                    {available ? (
                      <CheckCircle color="success" sx={{ mr: 1, fontSize: 20 }} />
                    ) : (
                      <Warning color="warning" sx={{ mr: 1, fontSize: 20 }} />
                    )}
                    <Typography variant="body2">
                      {lob}
                    </Typography>
                  </Box>
                ))}
              </Box>
              <Divider sx={{ my: 2 }} />
              <Typography variant="body2" color="text.secondary">
                Ready: {systemStatus?.lob_status ? 
                  Object.values(systemStatus.lob_status).filter(Boolean).length : 0
                } / {systemStatus?.lob_status ? Object.keys(systemStatus.lob_status).length : 0} LOBs
              </Typography>
            </CardContent>
          </Card>
        </Grid>

        {/* System Resources */}
        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                System Resources
              </Typography>
              {systemStatus?.disk_usage && (
                <Box>
                  <Box sx={{ mb: 2 }}>
                    <Typography variant="body2" color="text.secondary">
                      Output Files: {systemStatus.disk_usage.output_mb} MB
                    </Typography>
                    <LinearProgress 
                      variant="determinate" 
                      value={Math.min((systemStatus.disk_usage.output_mb / 100) * 100, 100)} 
                      sx={{ mt: 0.5 }}
                    />
                  </Box>
                  <Box sx={{ mb: 2 }}>
                    <Typography variant="body2" color="text.secondary">
                      Log Files: {systemStatus.disk_usage.logs_mb} MB
                    </Typography>
                    <LinearProgress 
                      variant="determinate" 
                      value={Math.min((systemStatus.disk_usage.logs_mb / 50) * 100, 100)} 
                      sx={{ mt: 0.5 }}
                    />
                  </Box>
                  <Box>
                    <Typography variant="body2" color="text.secondary">
                      Data Files: {systemStatus.disk_usage.data_mb} MB
                    </Typography>
                    <LinearProgress 
                      variant="determinate" 
                      value={Math.min((systemStatus.disk_usage.data_mb / 200) * 100, 100)} 
                      sx={{ mt: 0.5 }}
                    />
                  </Box>
                </Box>
              )}
            </CardContent>
          </Card>
        </Grid>

        {/* Job Statistics */}
        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Job Statistics
              </Typography>
              {systemStatus?.jobs && (
                <Grid container spacing={2}>
                  <Grid item xs={6}>
                    <Box textAlign="center">
                      <Typography variant="h4" color="primary">
                        {systemStatus.jobs.total}
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        Total Jobs
                      </Typography>
                    </Box>
                  </Grid>
                  <Grid item xs={6}>
                    <Box textAlign="center">
                      <Typography variant="h4" color="success.main">
                        {systemStatus.jobs.completed}
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        Completed
                      </Typography>
                    </Box>
                  </Grid>
                  <Grid item xs={6}>
                    <Box textAlign="center">
                      <Typography variant="h4" color="warning.main">
                        {systemStatus.jobs.running}
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        Running
                      </Typography>
                    </Box>
                  </Grid>
                  <Grid item xs={6}>
                    <Box textAlign="center">
                      <Typography variant="h4" color="error.main">
                        {systemStatus.jobs.failed}
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        Failed
                      </Typography>
                    </Box>
                  </Grid>
                </Grid>
              )}
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Connection Status Footer */}
      <Card sx={{ mt: 3 }}>
        <CardContent>
          <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
            <Box sx={{ display: 'flex', alignItems: 'center' }}>
              <Info color="primary" sx={{ mr: 1 }} />
              <Typography variant="body2">
                WebSocket: {connectionStatus === 'connected' ? 'Connected' : 'Disconnected'}
              </Typography>
            </Box>
            <Typography variant="body2" color="text.secondary">
              Last updated: {new Date().toLocaleTimeString()}
            </Typography>
          </Box>
        </CardContent>
      </Card>
    </Box>
  );
};

export default Dashboard;
